setup:
CREATE TABLE pipeline AS SELECT * FROM (VALUES
  (ST_GeomFromText('LINESTRING(0 0, 100 0, 200 50)'))
) t(geom);

CREATE TABLE sensors AS SELECT * FROM (VALUES
  (1, 'S-Alpha',   ST_Point(50, 30)),
  (2, 'S-Bravo',   ST_Point(120, 20)),
  (3, 'S-Charlie', ST_Point(150, 90)),
  (4, 'S-Delta',   ST_Point(10, -45)),
  (5, 'S-Echo',    ST_Point(300, 60))
) t(sensor_id, sensor_name, geom);

solution:
LOAD spatial;

SELECT s.sensor_id, s.sensor_name
FROM sensors s, pipeline p
WHERE ST_DWithin(s.geom, p.geom, 50)
ORDER BY s.sensor_id;
